/**
 * Text Object Model — the single source of truth for every piece of text in a document.
 *
 * A text object lives on a layer (`PixelLayerRuntime.text`). The layer's `indices` are only a
 * derived raster cache of this object, regenerated by `rasterizeTextObject`; the object itself
 * is what gets edited, serialised and restored. This module has no DOM and no imports from the
 * rest of the pixel engine so it can be shared by layout, raster, persistence and history.
 */

export const PIXEL_TEXT_ALIGNS = ["left", "center", "right", "justify"] as const
export type PixelTextAlign = (typeof PIXEL_TEXT_ALIGNS)[number]

export const PIXEL_TEXT_VALIGNS = ["top", "middle", "bottom"] as const
export type PixelTextVAlign = (typeof PIXEL_TEXT_VALIGNS)[number]

export const PIXEL_TEXT_OVERFLOWS = ["clip", "visible"] as const
export type PixelTextOverflow = (typeof PIXEL_TEXT_OVERFLOWS)[number]

export type PixelTextWeight = "normal" | "bold"
export type PixelTextStyle = "normal" | "italic"

export type PixelTextObject = {
  /** Unique id, stable across edits, history and reloads. */
  id: string
  text: string
  /** Top-left of the (unrotated) box, in document pixels. */
  x: number
  y: number
  /** Box size in document pixels. Resizing the box never changes `fontSize`. */
  width: number
  height: number
  fontFamily: string
  /** Glyph height in document pixels. Pixel fonts snap this to whole multiples of their native size. */
  fontSize: number
  fontWeight: PixelTextWeight
  fontStyle: PixelTextStyle
  /** `#RRGGBB`. Resolved to a palette index when rasterised. */
  color: string
  align: PixelTextAlign
  verticalAlign: PixelTextVAlign
  /** Multiplier of the font's native cell height. */
  lineHeight: number
  /** Extra advance between glyphs, in font units (one unit = one font pixel, scaled with the font). */
  letterSpacing: number
  /** 0-100. Mirrors the owning layer's opacity (the compositor applies it). */
  opacity: number
  /** Degrees, clockwise, about the centre of the box. */
  rotation: number
  visible: boolean
  locked: boolean
  overflow: PixelTextOverflow
}

export const PIXEL_TEXT_DEFAULT_FONT = "pixel-5x7"
export const PIXEL_TEXT_MAX_CHARS = 2000
export const PIXEL_TEXT_MIN_BOX = 1
export const PIXEL_TEXT_LINE_HEIGHT_MIN = 0.5
export const PIXEL_TEXT_LINE_HEIGHT_MAX = 4
export const PIXEL_TEXT_LETTER_SPACING_MIN = -2
export const PIXEL_TEXT_LETTER_SPACING_MAX = 16
export const PIXEL_TEXT_FONT_SIZE_MAX = 256
/** Default click-to-create box (document pixels). */
export const PIXEL_TEXT_DEFAULT_BOX = { width: 48, height: 16 } as const

export function createTextId() {
  return `text_${Math.random().toString(36).slice(2, 10)}${Date.now().toString(36).slice(-3)}`
}

export function createTextObject(partial: Partial<PixelTextObject> = {}): PixelTextObject {
  return normalizeTextObject({
    id: createTextId(),
    text: "",
    x: 0,
    y: 0,
    width: PIXEL_TEXT_DEFAULT_BOX.width,
    height: PIXEL_TEXT_DEFAULT_BOX.height,
    fontFamily: PIXEL_TEXT_DEFAULT_FONT,
    fontSize: 7,
    fontWeight: "normal",
    fontStyle: "normal",
    color: "#20202A",
    align: "left",
    verticalAlign: "top",
    lineHeight: 1.15,
    letterSpacing: 1,
    opacity: 100,
    rotation: 0,
    visible: true,
    locked: false,
    overflow: "visible",
    ...partial,
  })!
}

function num(value: unknown, fallback: number) {
  return typeof value === "number" && Number.isFinite(value) ? value : fallback
}

function clamp(value: number, min: number, max: number) {
  return Math.max(min, Math.min(max, value))
}

function oneOf<T extends string>(value: unknown, list: readonly T[], fallback: T): T {
  return typeof value === "string" && (list as readonly string[]).includes(value) ? (value as T) : fallback
}

/** Normalise degrees into [0, 360). */
export function normalizeRotation(degrees: number) {
  const mod = ((degrees % 360) + 360) % 360
  return Math.round(mod * 100) / 100
}

function hex(value: unknown, fallback: string) {
  if (typeof value !== "string") return fallback
  const match = /^#?([0-9a-fA-F]{6})$/.exec(value.trim())
  return match ? `#${match[1]!.toUpperCase()}` : fallback
}

/**
 * Lenient parse + clamp. Anything missing or malformed falls back to a default so a document
 * written by a newer or older client still opens. Returns null only when `raw` is not an object.
 */
export function normalizeTextObject(raw: unknown): PixelTextObject | null {
  if (!raw || typeof raw !== "object") return null
  const r = raw as Record<string, unknown>
  const text = typeof r.text === "string" ? r.text.replace(/\r\n?/g, "\n").slice(0, PIXEL_TEXT_MAX_CHARS) : ""
  return {
    id: typeof r.id === "string" && r.id ? r.id.slice(0, 64) : createTextId(),
    text,
    x: Math.round(num(r.x, 0)),
    y: Math.round(num(r.y, 0)),
    width: Math.max(PIXEL_TEXT_MIN_BOX, Math.round(num(r.width, PIXEL_TEXT_DEFAULT_BOX.width))),
    height: Math.max(PIXEL_TEXT_MIN_BOX, Math.round(num(r.height, PIXEL_TEXT_DEFAULT_BOX.height))),
    fontFamily:
      typeof r.fontFamily === "string" && r.fontFamily ? r.fontFamily.slice(0, 64) : PIXEL_TEXT_DEFAULT_FONT,
    fontSize: clamp(Math.round(num(r.fontSize, 7)), 1, PIXEL_TEXT_FONT_SIZE_MAX),
    fontWeight: oneOf(r.fontWeight, ["normal", "bold"] as const, "normal"),
    fontStyle: oneOf(r.fontStyle, ["normal", "italic"] as const, "normal"),
    color: hex(r.color, "#20202A"),
    align: oneOf(r.align, PIXEL_TEXT_ALIGNS, "left"),
    verticalAlign: oneOf(r.verticalAlign, PIXEL_TEXT_VALIGNS, "top"),
    lineHeight: clamp(
      Math.round(num(r.lineHeight, 1.15) * 100) / 100,
      PIXEL_TEXT_LINE_HEIGHT_MIN,
      PIXEL_TEXT_LINE_HEIGHT_MAX,
    ),
    letterSpacing: clamp(
      Math.round(num(r.letterSpacing, 1)),
      PIXEL_TEXT_LETTER_SPACING_MIN,
      PIXEL_TEXT_LETTER_SPACING_MAX,
    ),
    opacity: clamp(Math.round(num(r.opacity, 100)), 0, 100),
    rotation: normalizeRotation(num(r.rotation, 0)),
    visible: r.visible !== false,
    locked: r.locked === true,
    overflow: oneOf(r.overflow, PIXEL_TEXT_OVERFLOWS, "visible"),
  }
}

export function cloneTextObject(text: PixelTextObject): PixelTextObject {
  return { ...text }
}

const KEYS: readonly (keyof PixelTextObject)[] = [
  "id", "text", "x", "y", "width", "height", "fontFamily", "fontSize", "fontWeight", "fontStyle",
  "color", "align", "verticalAlign", "lineHeight", "letterSpacing", "opacity", "rotation",
  "visible", "locked", "overflow",
]

export function textObjectsEqual(a: PixelTextObject | undefined | null, b: PixelTextObject | undefined | null) {
  if (a === b) return true
  if (!a || !b) return false
  for (const key of KEYS) if (a[key] !== b[key]) return false
  return true
}

/** Fields whose change alters the rasterised pixels (everything except pure bookkeeping). */
export function textObjectRasterKey(t: PixelTextObject) {
  return [
    t.text, t.x, t.y, t.width, t.height, t.fontFamily, t.fontSize, t.fontWeight, t.fontStyle,
    t.color, t.align, t.verticalAlign, t.lineHeight, t.letterSpacing, t.rotation, t.overflow,
  ].join("\u0001")
}
